.darma-loader-darma-b7-pie-clock-fill { --accent: var(--loader-color, #06b6d4); --accent-2: var(--loader-secondary-color, #0e7490); width: var(--loader-size, 72px); height: var(--loader-size, 72px); border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 22%, transparent); position: relative; overflow: hidden; }
.darma-loader-darma-b7-pie-clock-fill::before, .darma-loader-darma-b7-pie-clock-fill::after { content: ''; position: absolute; top: 0; left: 50%; width: 50%; height: 100%; background: var(--accent); transform-origin: left center; }
.darma-loader-darma-b7-pie-clock-fill::before { animation: darma-loader-darma-b7-pie-clock-fill-pie-a calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b7-pie-clock-fill::after { animation: darma-loader-darma-b7-pie-clock-fill-pie-b calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
@keyframes darma-loader-darma-b7-pie-clock-fill-pie-a { 0% { transform: rotate(0deg); } 50%, 100% { transform: rotate(180deg); } }
@keyframes darma-loader-darma-b7-pie-clock-fill-pie-b { 0%, 50% { transform: rotate(0deg); } 100% { transform: rotate(180deg); } }

